sp_widget.client_script:
api.controller=function() {
  /* widget controller */
  var c = this;
};

sp_widget.css:
.wrm-qa h2 {
  margin: 0 0 12px;
  font-size: 22px;
  color: var(--ink);
}

.wrm-qa-btn {
  display: block;
  width: 100%;
  text-align: center;
  font-size: 14px;
  font-weight: 500;
  padding: 12px 18px;
  margin-bottom: 9px;
  border-radius: var(--r-pill);
  background: transparent;
  color: var(--ink-2);
  box-shadow: inset 0 0 0 1px var(--line);
  text-decoration: none;
}
.wrm-qa-btn:hover,
.wrm-qa-btn:focus {
  background: var(--surface-2);
  color: var(--ink);
  text-decoration: none;
}
.wrm-qa-btn:focus-visible {
  outline: 2px solid var(--clay);
  outline-offset: 3px;
}

.wrm-qa-btn.primary {
  background: var(--clay);
  color: var(--on-clay);
  box-shadow: inset 0 0 0 1px rgba(255,255,255,.22);
}
.wrm-qa-btn.primary:hover,
.wrm-qa-btn.primary:focus {
  background: var(--clay-press);
  color: var(--on-clay);
}

.wrm-qa-btn:last-child { margin-bottom: 0; }
